namespace r2port::ao::xegtao {
namespace {

using Microsoft::WRL::ComPtr;

// Same layout as XeGTAO::GTAOConstants (XeGTAO.h, Intel, MIT): 96 bytes, HLSL cbuffer packing.
struct GTAOConstants {
    int   ViewportSize[2];
    float ViewportPixelSize[2];
    float DepthUnpackConsts[2];
    float CameraTanHalfFOV[2];
    float NDCToViewMul[2];
    float NDCToViewAdd[2];
    float NDCToViewMul_x_PixelSize[2];
    float EffectRadius;
    float EffectFalloffRange;
    float RadiusMultiplier;
    float Padding0;
    float FinalValuePower;
    float DenoiseBlurBeta;
    float SampleDistributionPower;
    float ThinOccluderCompensation;
    float DepthMIPSamplingOffset;
    int   NoiseIndex;
};
static_assert(sizeof(GTAOConstants) == 96, "cbuffer layout");

struct SourceConstants { float offset[2]; float invSize[2]; };   // b1 (R2SourceCB)

// XeGTAO defaults (XeGTAO.h XE_GTAO_DEFAULT_*)
constexpr float kRadiusMultiplier = 1.457f, kFalloffRange = 0.615f, kSampleDistPower = 2.0f, kThinOccluder = 0.0f, kFinalPower = 2.2f, kMipOffset = 3.30f;
// Strength matching: FinalValuePower scale per quality tier so that the mean AO (z < 2000 units) matches HBAO+ at R1's defaults (radius 1 m,
// power 4, blur 8). Averaged over two synthetic scenes at 1080p with 2 denoise passes; per scene the needed power differs by about +-15 %
// (outdoor wants less, the corridor more), see bench/RESULTS2.md.
constexpr float kTierPowerScale[3] = { 1.30f, 1.58f, 1.03f };
constexpr int   kSlices[3] = { 1, 2, 3 }, kSteps[3] = { 2, 2, 3 };
constexpr int   kMinViewport = 64;

struct Tex {
    ComPtr<ID3D11Texture2D> tex; ComPtr<ID3D11ShaderResourceView> srv; std::vector<ComPtr<ID3D11UnorderedAccessView>> uav; int w = 0, h = 0;
    void reset() { tex.Reset(); srv.Reset(); uav.clear(); w = h = 0; }
};

enum Kind { kPrefilter, kNormals, kMain, kDenoise, kDenoiseLast, kDownsample, kUpsample };

struct State {
    ComPtr<ID3D11Device> dev;
    ComPtr<ID3D11SamplerState> samp;
    ComPtr<ID3D11Buffer> cbFull, cbHalf, cbSrcVp, cbSrcHalf;
    std::string hlsl;
    std::map<uint32_t, ComPtr<ID3D11ComputeShader>> shaders;
    Tex depthWork, normals, aoA, aoB, edges, halfDepth, aoFinalHalf;
    int w = 0, h = 0; bool half = false, fp32 = false, needB = false;
    std::string err;
} g;

bool fail(const std::string& s) { g.err = s; return false; }

ComPtr<ID3D11ComputeShader> getShader(Kind kind, int quality, bool fp32)
{
    if (kind == kDownsample || kind == kUpsample) fp32 = false;
    if (kind != kMain) quality = 0;
    uint32_t key = (uint32_t)kind | ((uint32_t)quality << 4) | ((uint32_t)fp32 << 8);
    auto it = g.shaders.find(key); if (it != g.shaders.end()) return it->second;

    std::vector<D3D_SHADER_MACRO> defs; std::string slices = std::to_string(kSlices[quality]), steps = std::to_string(kSteps[quality]);
    const char* entry = "";
    switch (kind) {
    case kPrefilter:        defs.push_back({ "R2_PASS_PREFILTER", "1" }); entry = "CSPrefilter"; break;
    case kNormals:          defs.push_back({ "R2_PASS_NORMALS", "1" });   entry = "CSNormals"; break;
    case kMain:             defs.push_back({ "R2_PASS_MAIN", "1" }); defs.push_back({ "R2_SLICES", slices.c_str() }); defs.push_back({ "R2_STEPS", steps.c_str() }); entry = "CSMain"; break;
    case kDenoise:          defs.push_back({ "R2_PASS_DENOISE", "1" }); entry = "CSDenoise"; break;
    case kDenoiseLast:      defs.push_back({ "R2_PASS_DENOISE", "1" }); entry = "CSDenoiseLast"; break;
    case kDownsample:       defs.push_back({ "R2_PASS_DOWNSAMPLE", "1" }); entry = "CSDownsample"; break;
    case kUpsample:         defs.push_back({ "R2_PASS_UPSAMPLE", "1" }); entry = "CSUpsample"; break;
    }
    if (fp32) { defs.push_back({ "XE_GTAO_FP32_DEPTHS", "1" }); defs.push_back({ "XE_GTAO_USE_HALF_FLOAT_PRECISION", "0" }); }
    defs.push_back({ nullptr, nullptr });
    ComPtr<ID3DBlob> blob, errs;
    HRESULT hr = D3DCompile(g.hlsl.data(), g.hlsl.size(), "r2_xegtao.hlsl", defs.data(), nullptr, entry, "cs_5_0", D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &blob, &errs);
    if (FAILED(hr)) { fail(std::string("D3DCompile ") + entry + " failed: " + (errs ? (const char*)errs->GetBufferPointer() : "?")); return nullptr; }
    ComPtr<ID3D11ComputeShader> cs;
    if (FAILED(g.dev->CreateComputeShader(blob->GetBufferPointer(), blob->GetBufferSize(), nullptr, &cs))) { fail(std::string("CreateComputeShader ") + entry); return nullptr; }
    g.shaders[key] = cs; return cs;
}

bool makeTex(Tex& t, int w, int h, DXGI_FORMAT fmt, int mips)
{
    t.reset(); t.w = w; t.h = h;
    D3D11_TEXTURE2D_DESC d = {}; d.Width = w; d.Height = h; d.MipLevels = mips; d.ArraySize = 1; d.Format = fmt; d.SampleDesc.Count = 1;
    d.Usage = D3D11_USAGE_DEFAULT; d.BindFlags = D3D11_BIND_SHADER_RESOURCE | D3D11_BIND_UNORDERED_ACCESS;
    if (FAILED(g.dev->CreateTexture2D(&d, nullptr, &t.tex))) return fail("CreateTexture2D failed");
    if (FAILED(g.dev->CreateShaderResourceView(t.tex.Get(), nullptr, &t.srv))) return fail("CreateShaderResourceView failed");
    for (int m = 0; m < mips; m++) {
        D3D11_UNORDERED_ACCESS_VIEW_DESC u = {}; u.Format = fmt; u.ViewDimension = D3D11_UAV_DIMENSION_TEXTURE2D; u.Texture2D.MipSlice = m;
        ComPtr<ID3D11UnorderedAccessView> v; if (FAILED(g.dev->CreateUnorderedAccessView(t.tex.Get(), &u, &v))) return fail("CreateUnorderedAccessView failed");
        t.uav.push_back(v);
    }
    return true;
}

bool makeCB(ComPtr<ID3D11Buffer>& b, UINT size)
{
    D3D11_BUFFER_DESC bd = {}; bd.ByteWidth = size; bd.Usage = D3D11_USAGE_DEFAULT; bd.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
    return SUCCEEDED(g.dev->CreateBuffer(&bd, nullptr, &b)) || fail("CreateBuffer(cbuffer) failed");
}

bool ensureTargets(int w, int h, bool half, bool fp32, bool needB)
{
    if (g.w == w && g.h == h && g.half == half && g.fp32 == fp32 && g.needB == needB && g.depthWork.tex) return true;
    const int aw = half ? (w + 1) / 2 : w, ah = half ? (h + 1) / 2 : h;
    bool ok = makeTex(g.depthWork, aw, ah, fp32 ? DXGI_FORMAT_R32_FLOAT : DXGI_FORMAT_R16_FLOAT, 5) && makeTex(g.normals, aw, ah, DXGI_FORMAT_R32_UINT, 1)
           && makeTex(g.aoA, aw, ah, DXGI_FORMAT_R8_UNORM, 1) && makeTex(g.edges, aw, ah, DXGI_FORMAT_R8_UNORM, 1);
    if (ok && needB) ok = makeTex(g.aoB, aw, ah, DXGI_FORMAT_R8_UNORM, 1); else g.aoB.reset();
    if (ok && half) ok = makeTex(g.halfDepth, aw, ah, DXGI_FORMAT_R32_FLOAT, 1) && makeTex(g.aoFinalHalf, aw, ah, DXGI_FORMAT_R8_UNORM, 1);
    else { g.halfDepth.reset(); g.aoFinalHalf.reset(); }
    if (!ok) { g.w = g.h = 0; return false; }
    g.w = w; g.h = h; g.half = half; g.fp32 = fp32; g.needB = needB; return true;
}

// XeGTAO.h GTAOUpdateConstants (rowMajor = true), with R1's projection
void fillConsts(GTAOConstants& c, int w, int h, const float* P, float radiusUnits, float finalPower, int noiseIndex)
{
    c.ViewportSize[0] = w; c.ViewportSize[1] = h;
    c.ViewportPixelSize[0] = 1.0f / (float)w; c.ViewportPixelSize[1] = 1.0f / (float)h;
    float mul = -P[3 * 4 + 2], add = P[2 * 4 + 2];
    if (mul * add < 0) add = -add;
    c.DepthUnpackConsts[0] = mul; c.DepthUnpackConsts[1] = add;
    float tanY = 1.0f / P[1 * 4 + 1], tanX = 1.0f / P[0 * 4 + 0];
    c.CameraTanHalfFOV[0] = tanX; c.CameraTanHalfFOV[1] = tanY;
    c.NDCToViewMul[0] = tanX * 2.0f; c.NDCToViewMul[1] = tanY * -2.0f;
    c.NDCToViewAdd[0] = tanX * -1.0f; c.NDCToViewAdd[1] = tanY * 1.0f;
    c.NDCToViewMul_x_PixelSize[0] = c.NDCToViewMul[0] * c.ViewportPixelSize[0]; c.NDCToViewMul_x_PixelSize[1] = c.NDCToViewMul[1] * c.ViewportPixelSize[1];
    c.EffectRadius = radiusUnits; c.EffectFalloffRange = kFalloffRange; c.DenoiseBlurBeta = 1.2f;
    c.RadiusMultiplier = kRadiusMultiplier; c.SampleDistributionPower = kSampleDistPower; c.ThinOccluderCompensation = kThinOccluder;
    c.FinalValuePower = finalPower; c.DepthMIPSamplingOffset = kMipOffset; c.NoiseIndex = noiseIndex; c.Padding0 = 0;
}

bool formatUavStore(DXGI_FORMAT f)
{
    D3D11_FEATURE_DATA_FORMAT_SUPPORT2 s = { f, 0 };
    return SUCCEEDED(g.dev->CheckFeatureSupport(D3D11_FEATURE_FORMAT_SUPPORT2, &s, sizeof(s))) && (s.OutFormatSupport2 & D3D11_FORMAT_SUPPORT2_UAV_TYPED_STORE);
}

void unbind(ID3D11DeviceContext* ctx)
{
    ID3D11ShaderResourceView* ns[3] = {}; ID3D11UnorderedAccessView* nu[5] = {}; ID3D11Buffer* nb[2] = {}; ID3D11SamplerState* nsamp[1] = {};
    ctx->CSSetShaderResources(0, 3, ns); ctx->CSSetUnorderedAccessViews(0, 5, nu, nullptr); ctx->CSSetConstantBuffers(0, 2, nb);
    ctx->CSSetSamplers(0, 1, nsamp); ctx->CSSetShader(nullptr, nullptr, 0);
}

} // namespace

const char* LastError() { return g.err.c_str(); }

void Shutdown() { g = State(); }

bool Init(ID3D11Device* device)
{
    if (!device) return fail("null device");
    if (g.dev.Get() == device && g.samp) return true;
    Shutdown(); g.dev = device;
    if (g.dev->GetFeatureLevel() < D3D_FEATURE_LEVEL_11_0) return fail("feature level below 11_0");
    const DXGI_FORMAT need[] = { DXGI_FORMAT_R16_FLOAT, DXGI_FORMAT_R32_FLOAT, DXGI_FORMAT_R8_UNORM, DXGI_FORMAT_R32_UINT };
    for (DXGI_FORMAT f : need) if (!formatUavStore(f)) return fail("typed UAV store unsupported for DXGI format " + std::to_string((int)f));
    for (const char* c : kHlslChunks) g.hlsl += c;
    D3D11_SAMPLER_DESC sd = {}; sd.Filter = D3D11_FILTER_MIN_MAG_MIP_POINT; sd.AddressU = sd.AddressV = sd.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP; sd.MaxLOD = D3D11_FLOAT32_MAX;
    if (FAILED(g.dev->CreateSamplerState(&sd, &g.samp))) return fail("CreateSamplerState failed");
    if (!makeCB(g.cbFull, sizeof(GTAOConstants)) || !makeCB(g.cbHalf, sizeof(GTAOConstants)) || !makeCB(g.cbSrcVp, sizeof(SourceConstants)) || !makeCB(g.cbSrcHalf, sizeof(SourceConstants))) return false;
    // compile the default (fp16, all tiers) set now so that Render() never hitches
    for (Kind k : { kPrefilter, kNormals, kDenoise, kDenoiseLast, kDownsample, kUpsample }) if (!getShader(k, 0, false)) return false;
    for (int q = 0; q < 3; q++) if (!getShader(kMain, q, false)) return false;
    g.err.clear(); return true;
}

bool Render(ID3D11DeviceContext* ctx, ID3D11ShaderResourceView* depthSrv, const float P[16], float metersToView, const D3D11_VIEWPORT& vp,
            ID3D11UnorderedAccessView* outAoUav, const Params& prm)
{
    if (!g.samp) return fail("Init() was not called");
    if (!ctx || !depthSrv || !outAoUav || !P) return fail("null argument");
    const int w = (int)vp.Width, h = (int)vp.Height, ox = (int)vp.TopLeftX, oy = (int)vp.TopLeftY;
    if (w < kMinViewport || h < kMinViewport) return fail("viewport smaller than 64x64");
    if (!(std::fabs(P[0]) > 1e-6f) || !(std::fabs(P[5]) > 1e-6f) || !std::isfinite(P[10]) || !std::isfinite(P[14])) return fail("invalid projection matrix");
    int sw = prm.sceneWidth, sh = prm.sceneHeight;
    if (sw <= 0 || sh <= 0) {
        ComPtr<ID3D11Resource> r; depthSrv->GetResource(&r); ComPtr<ID3D11Texture2D> t;
        if (!r || FAILED(r.As(&t))) return fail("depth SRV is not a Texture2D"); D3D11_TEXTURE2D_DESC d; t->GetDesc(&d); sw = (int)d.Width; sh = (int)d.Height;
    }
    const int quality = std::clamp(prm.quality, 0, 2), passes = std::clamp(prm.denoisePasses, 1, 3);
    const bool half = prm.halfRes, fp32 = prm.fp32DepthMips;
    if (!ensureTargets(w, h, half, fp32, passes >= 2)) return false;
    const int aw = g.depthWork.w, ah = g.depthWork.h;

    const float power = prm.finalValuePower > 0 ? prm.finalValuePower : kFinalPower * kTierPowerScale[quality] * std::max(prm.intensity, 0.01f);
    const float radiusUnits = std::max(prm.radiusMeters, 0.001f) * metersToView;
    const int noise = ((prm.frameIndex % 64) + 64) % 64;
    GTAOConstants cf, ch; fillConsts(cf, w, h, P, radiusUnits, power, noise); fillConsts(ch, aw, ah, P, radiusUnits, power, noise);
    SourceConstants sv = { { (float)ox, (float)oy }, { 1.0f / (float)sw, 1.0f / (float)sh } }, shf = { { 0, 0 }, { 1.0f / (float)aw, 1.0f / (float)ah } };
    ctx->UpdateSubresource(g.cbFull.Get(), 0, nullptr, &cf, 0, 0); ctx->UpdateSubresource(g.cbSrcVp.Get(), 0, nullptr, &sv, 0, 0);
    if (half) { ctx->UpdateSubresource(g.cbHalf.Get(), 0, nullptr, &ch, 0, 0); ctx->UpdateSubresource(g.cbSrcHalf.Get(), 0, nullptr, &shf, 0, 0); }

    auto csPre = getShader(kPrefilter, 0, fp32), csNrm = getShader(kNormals, 0, fp32), csMain = getShader(kMain, quality, fp32), csDen = getShader(kDenoise, 0, fp32),
         csLast = getShader(kDenoiseLast, 0, fp32), csDown = getShader(kDownsample, 0, false), csUp = getShader(kUpsample, 0, false);
    if (!csPre || !csNrm || !csMain || !csDen || !csLast || !csDown || !csUp) return false;

    auto groups = [](int n, int d) { return (UINT)((n + d - 1) / d); };
    ID3D11Buffer* cbs[2];
    auto setCbs = [&](ID3D11Buffer* b0, ID3D11Buffer* b1) { cbs[0] = b0; cbs[1] = b1; ctx->CSSetConstantBuffers(0, 2, cbs); };
    ID3D11SamplerState* samp = g.samp.Get(); ctx->CSSetSamplers(0, 1, &samp);
    ID3D11Buffer* aB0 = half ? g.cbHalf.Get() : g.cbFull.Get(); ID3D11Buffer* aB1 = half ? g.cbSrcHalf.Get() : g.cbSrcVp.Get();   // AO-resolution constants
    ID3D11ShaderResourceView* aoDepthSrv = half ? g.halfDepth.srv.Get() : depthSrv;

    if (half) {   // 0. downsample the viewport region of the depth texture
        setCbs(g.cbFull.Get(), g.cbSrcVp.Get()); ctx->CSSetShader(csDown.Get(), nullptr, 0); ctx->CSSetShaderResources(0, 1, &depthSrv);
        ID3D11UnorderedAccessView* u = g.halfDepth.uav[0].Get(); ctx->CSSetUnorderedAccessViews(0, 1, &u, nullptr); ctx->Dispatch(groups(aw, 8), groups(ah, 8), 1); unbind(ctx);
        ctx->CSSetSamplers(0, 1, &samp);
    }
    {   // 1. normals from depth
        setCbs(aB0, aB1); ctx->CSSetShader(csNrm.Get(), nullptr, 0); ctx->CSSetShaderResources(0, 1, &aoDepthSrv);
        ID3D11UnorderedAccessView* u = g.normals.uav[0].Get(); ctx->CSSetUnorderedAccessViews(0, 1, &u, nullptr); ctx->Dispatch(groups(aw, 8), groups(ah, 8), 1);
        ID3D11ShaderResourceView* ns = nullptr; ctx->CSSetShaderResources(0, 1, &ns); ID3D11UnorderedAccessView* nu = nullptr; ctx->CSSetUnorderedAccessViews(0, 1, &nu, nullptr);
    }
    {   // 2. depth MIP prefilter (5 MIPs, 16x16 pixels per group)
        ctx->CSSetShader(csPre.Get(), nullptr, 0); ctx->CSSetShaderResources(0, 1, &aoDepthSrv);
        ID3D11UnorderedAccessView* u[5]; for (int i = 0; i < 5; i++) u[i] = g.depthWork.uav[i].Get();
        ctx->CSSetUnorderedAccessViews(0, 5, u, nullptr); ctx->Dispatch(groups(aw, 16), groups(ah, 16), 1);
        ID3D11ShaderResourceView* ns = nullptr; ctx->CSSetShaderResources(0, 1, &ns); ID3D11UnorderedAccessView* nu[5] = {}; ctx->CSSetUnorderedAccessViews(0, 5, nu, nullptr);
    }
    {   // 3. main pass: AO term + edges
        ctx->CSSetShader(csMain.Get(), nullptr, 0); ID3D11ShaderResourceView* s[2] = { g.depthWork.srv.Get(), g.normals.srv.Get() }; ctx->CSSetShaderResources(0, 2, s);
        ID3D11UnorderedAccessView* u[2] = { g.aoA.uav[0].Get(), g.edges.uav[0].Get() }; ctx->CSSetUnorderedAccessViews(0, 2, u, nullptr); ctx->Dispatch(groups(aw, 8), groups(ah, 8), 1);
        ID3D11ShaderResourceView* ns[2] = {}; ctx->CSSetShaderResources(0, 2, ns); ID3D11UnorderedAccessView* nu[2] = {}; ctx->CSSetUnorderedAccessViews(0, 2, nu, nullptr);
    }
    // 4. denoise: each thread does 2 horizontal pixels. 1 pass: A -> final; 2: A -> B -> final; 3: A -> B -> A -> final
    Tex* ping[2] = { &g.aoB, &g.aoA }; Tex* src = &g.aoA;
    for (int p = 0; p < passes; p++) {
        const bool last = (p == passes - 1);
        ID3D11ComputeShader* cs = !last ? csDen.Get() : csLast.Get();
        ID3D11UnorderedAccessView* dst = !last ? ping[p & 1]->uav[0].Get() : (half ? g.aoFinalHalf.uav[0].Get() : outAoUav);
        ctx->CSSetShader(cs, nullptr, 0); ID3D11ShaderResourceView* s[2] = { src->srv.Get(), g.edges.srv.Get() }; ctx->CSSetShaderResources(0, 2, s);
        ctx->CSSetUnorderedAccessViews(0, 1, &dst, nullptr); ctx->Dispatch(groups(aw, 16), groups(ah, 8), 1);
        ID3D11ShaderResourceView* ns[2] = {}; ctx->CSSetShaderResources(0, 2, ns); ID3D11UnorderedAccessView* nu = nullptr; ctx->CSSetUnorderedAccessViews(0, 1, &nu, nullptr);
        if (!last) src = ping[p & 1];
    }
    if (half) {   // 5. bilateral upsample into the caller's R16_UNORM output
        setCbs(g.cbFull.Get(), g.cbSrcVp.Get()); ctx->CSSetShader(csUp.Get(), nullptr, 0);
        ID3D11ShaderResourceView* s[3] = { g.aoFinalHalf.srv.Get(), g.halfDepth.srv.Get(), depthSrv }; ctx->CSSetShaderResources(0, 3, s);
        ctx->CSSetUnorderedAccessViews(0, 1, &outAoUav, nullptr); ctx->Dispatch(groups(w, 8), groups(h, 8), 1);
    }
    unbind(ctx);
    return true;
}

} // namespace r2port::ao::xegtao
